
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_pkzb_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_pkzb", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.451308961472306e-02, -6.369340885942339e-02, -6.251134446891105e-02, -6.080404452222980e-02, -5.833181574573583e-02, -5.473749266282452e-02, -4.948417689444368e-02, -4.179610125532233e-02, -3.090571168278915e-02, -1.815354057776852e-02, -1.210921981336251e-02, -3.796752496088870e-02, -4.543585520252614e-02, -3.040716887226967e-02, -1.613281324044913e-02, -3.768548663517878e-03, -1.809986508216725e-04, -1.020212609705915e-06, -3.052922605797284e-10, -9.572858715595206e-16]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


